cat >> parser_test.go <<'EOF'

func TestExpand(t *testing.T) {
	t.Setenv("KV_SET", "val")
	t.Setenv("KV_EMPTY", "")
	text := "[s]\na = ${KV_SET}/x\nb = \"${KV_EMPTY:-fb}\"\nc = ${KV_SET:-fb}\nd = $$5 $x\n"
	c := mustParse(t, text)
	for key, want := range map[string]string{"a": "val/x", "b": "fb", "c": "val", "d": "$5 $x"} {
		if got := get(t, c, "s", key); got != want {
			t.Errorf("%s = %q, want %q", key, got, want)
		}
	}
	c, err := ParseWithOptions(strings.NewReader(text), ParseOptions{NoExpand: true})
	if err != nil {
		t.Fatal(err)
	}
	if got := get(t, c, "s", "a"); got != "${KV_SET}/x" {
		t.Errorf("NoExpand a = %q", got)
	}
	_, err = Parse(strings.NewReader("a = 1\nb = ${KV_UNSET_XYZ}\n"))
	if err == nil || err.Error() != `kvconf: line 2: undefined variable "KV_UNSET_XYZ"` {
		t.Errorf("error = %v", err)
	}
}
EOF
cat >> README.md <<'EOF'

## Environment variables

Unquoted and double-quoted values expand `${NAME}` and `${NAME:-fallback}`
(the fallback is used when `NAME` is unset or empty). `$$` is a literal `$`;
a `$` followed by anything else is kept. An unset variable without a fallback
is an error. Use `ParseWithOptions(r, ParseOptions{NoExpand: true})`, or
`kvconf get --no-expand FILE KEY` / `kvconf dump --no-expand FILE`, to keep
values literally.
EOF
